import type { CSSProperties } from "react"

import type { ButtonGroupHighlightProps } from "./button-group.types"
import { buttonGroupHighlightClasses } from "./button-group.variants"

/** The hover fill, shared by every item so it slides from one to the next. */
export function ButtonGroupHighlight({ state }: ButtonGroupHighlightProps) {
  return (
    <span
      aria-hidden="true"
      data-slot="button-group-highlight"
      data-visible={state.visible ? "" : undefined}
      data-instant={state.instant ? "" : undefined}
      className={buttonGroupHighlightClasses}
      style={
        {
          "--button-group-highlight-left": `${state.left}px`,
          "--button-group-highlight-top": `${state.top}px`,
          "--button-group-highlight-width": `${state.width}px`,
          "--button-group-highlight-height": `${state.height}px`,
        } as CSSProperties
      }
    />
  )
}

"use client"

import { use } from "react"
import { SegmentedControlItem } from "@ui-sdk/react/segmented-control"
import { Toggle } from "@ui-sdk/react/toggle"

// Import other registry components by exact file, not their folder's index.ts.
import { Button } from "@/components/ui/button/button"
import { cn } from "@/lib/cn"

import { ButtonGroupContext } from "./button-group.constants"
import type { ButtonGroupItemProps } from "./button-group.types"
import { buttonGroupItemClasses, buttonGroupItemPadding } from "./button-group.variants"
import { ButtonGroupLed } from "./button-group-led"

// ui-sdk's item keeps the behavior (radio or pressed toggle, arrow keys); the registry Button draws it.
export function ButtonGroupItem({
  value,
  icon,
  startIcon,
  endIcon,
  tooltip,
  disabled,
  className,
  children,
  "aria-label": ariaLabel,
  ...props
}: ButtonGroupItemProps) {
  const context = use(ButtonGroupContext)
  if (context == null) throw new Error("ButtonGroupItem must be inside a ButtonGroup.")
  const { selection, color, size } = context
  // An icon already marks the item, so the LED only shows on text-only items.
  const hasIcon = startIcon != null || endIcon != null

  const draw = (partProps: object, on: boolean) => (
    // ui-sdk's part props (role, aria-checked, handlers, tabIndex) go last so the consumer's can't replace them.
    <Button
      {...props}
      {...partProps}
      variant={on ? "solid" : "ghost"}
      color={on ? color : "muted"}
      padding={buttonGroupItemPadding[size]}
      radius="none"
      icon={icon}
      startIcon={startIcon}
      endIcon={endIcon}
      tooltip={tooltip}
      aria-label={ariaLabel}
      tapAnimation={false}
      data-button-group-item=""
      // The group's sliding highlight is the hover fill of unlit items.
      className={cn(buttonGroupItemClasses[selection], !on && "hover:bg-transparent", className)}
    >
      {icon == null && (
        <>
          {!hasIcon && <ButtonGroupLed on={on} size={size} />}
          {children}
        </>
      )}
    </Button>
  )

  // A disabled radio leaves ui-sdk's roving focus, but the Button keeps a disabled item with a
  // tooltip focusable (aria-disabled), which would add a second tab stop to the radio group.
  // tabIndex -1 keeps it out; its tooltip still opens on hover.
  return selection === "single" ? (
    <SegmentedControlItem
      value={value}
      disabled={disabled}
      render={(partProps, state) => draw(disabled ? { ...partProps, tabIndex: -1 } : partProps, state.checked)}
    />
  ) : (
    <Toggle value={value} disabled={disabled} render={(partProps, state) => draw(partProps, state.pressed)} />
  )
}

import { cn } from "@/lib/cn"

import type { ButtonGroupLedProps } from "./button-group.types"
import { buttonGroupLedClasses, buttonGroupLedSizeClasses } from "./button-group.variants"

export function ButtonGroupLed({ on, size }: ButtonGroupLedProps) {
  return (
    <span
      aria-hidden="true"
      data-slot="button-group-led"
      data-size={size}
      data-on={on ? "" : undefined}
      className={cn(buttonGroupLedClasses, buttonGroupLedSizeClasses[size])}
    />
  )
}

"use client"

import { ToggleGroup } from "@ui-sdk/react/toggle"

import type { ButtonGroupMultipleInternalProps } from "./button-group.types"
import { fromSdkMultiple, toSdkMultiple, useControllableValue } from "./use-button-group-value"

/** `selection="multiple"`: ui-sdk's toggle group, several items pressed at once. */
export function ButtonGroupMultiple({
  selection,
  value: valueProp,
  defaultValue = [],
  onValueChange,
  highlight,
  children,
  ...props
}: ButtonGroupMultipleInternalProps) {
  const [value, setValue] = useControllableValue({ value: valueProp, defaultValue, onValueChange })

  return (
    <ToggleGroup
      multiple
      data-selection={selection}
      value={toSdkMultiple(value)}
      onValueChange={(next, details) => {
        const mapped = fromSdkMultiple(next, value)
        if (mapped === undefined) details.cancel()
        else setValue(mapped)
      }}
      {...props}
    >
      {highlight}
      {children}
    </ToggleGroup>
  )
}

"use client"

import { useEffect, useRef } from "react"
import { SegmentedControl, SegmentedControlIndicator } from "@ui-sdk/react/segmented-control"

import type { ButtonGroupSingleInternalProps } from "./button-group.types"
import { buttonGroupIndicatorClasses } from "./button-group.variants"
import { fromSdkSingle, toSdkSingle, useControllableValue } from "./use-button-group-value"

/** `selection="single"`: ui-sdk's segmented control, a radio group with a sliding indicator. */
export function ButtonGroupSingle({
  selection,
  value: valueProp,
  defaultValue = null,
  onValueChange,
  hasAll,
  highlight,
  name,
  required,
  children,
  ...props
}: ButtonGroupSingleInternalProps) {
  const [value, setValue] = useControllableValue({ value: valueProp, defaultValue, onValueChange })

  // ui-sdk resets once per item (each has its own hidden input), before React re-renders with the
  // new value. Report the reset value once; the next render forgets it.
  const resetValueRef = useRef<{ value: string | null } | null>(null)
  useEffect(() => {
    resetValueRef.current = null
  })

  // With an All item, its hidden radio would submit the reserved value and always satisfy
  // `required`. So the group submits its own input instead: nothing while nothing is chosen.
  // "Nothing" is a valid choice then, so `required` has no effect.
  const ownInput = hasAll && name != null

  return (
    <SegmentedControl
      data-selection={selection}
      value={toSdkSingle(value)}
      onValueChange={(next, details) => {
        const mapped = fromSdkSingle(next)
        if (details.reason === "reset") {
          if (resetValueRef.current?.value === mapped) return
          resetValueRef.current = { value: mapped }
        }
        setValue(mapped)
      }}
      name={ownInput ? undefined : name}
      required={ownInput ? undefined : required}
      {...props}
    >
      {highlight}
      <SegmentedControlIndicator className={buttonGroupIndicatorClasses} />
      {children}
      {ownInput && value != null && <input type="hidden" name={name} value={value} />}
    </SegmentedControl>
  )
}

import { createContext } from "react"

import type { ButtonGroupContextValue } from "./button-group.types"

/** Value of `ButtonGroupAll` inside ui-sdk. It never reaches the consumer's value. */
export const BUTTON_GROUP_ALL = "__button-group-all__"

export const ButtonGroupContext = createContext<ButtonGroupContextValue | null>(null)

"use client"

import { useCallback, useMemo, useState } from "react"
import type { PointerEvent } from "react"

import { cn } from "@/lib/cn"

import { ButtonGroupContext } from "./button-group.constants"
import type { ButtonGroupProps } from "./button-group.types"
import {
  buttonGroupClasses,
  buttonGroupColorClasses,
  buttonGroupOrientationClasses,
  buttonGroupSizeClasses,
} from "./button-group.variants"
import { ButtonGroupHighlight } from "./button-group-highlight"
import { ButtonGroupMultiple } from "./button-group-multiple"
import { ButtonGroupSingle } from "./button-group-single"
import { useButtonGroupHighlight } from "./use-button-group-highlight"

export function ButtonGroup({ color = "primary", size = "md", className, ...props }: ButtonGroupProps) {
  // ButtonGroupAll registers itself, so single knows whether "nothing chosen" is a real choice.
  const [hasAll, setHasAll] = useState(false)
  const registerAll = useCallback(() => {
    setHasAll(true)
    return () => setHasAll(false)
  }, [])
  const context = useMemo(
    () => ({ selection: props.selection, color, size, registerAll }),
    [props.selection, color, size, registerAll]
  )
  const hover = useButtonGroupHighlight()
  const highlight = <ButtonGroupHighlight state={hover.state} />
  const { onPointerOver, onPointerLeave } = props
  const pointerHandlers = {
    onPointerOver: (event: PointerEvent<HTMLDivElement>) => {
      onPointerOver?.(event)
      hover.onPointerOver(event)
    },
    onPointerLeave: (event: PointerEvent<HTMLDivElement>) => {
      onPointerLeave?.(event)
      hover.onPointerLeave()
    },
  }
  const classes = cn(
    buttonGroupClasses,
    buttonGroupOrientationClasses[props.orientation ?? "horizontal"],
    buttonGroupColorClasses[color],
    buttonGroupSizeClasses[size],
    className
  )

  return (
    <ButtonGroupContext value={context}>
      {props.selection === "single" ? (
        <ButtonGroupSingle data-size={size} className={classes} hasAll={hasAll} highlight={highlight} {...props} {...pointerHandlers} />
      ) : (
        <ButtonGroupMultiple data-size={size} className={classes} highlight={highlight} {...props} {...pointerHandlers} />
      )}
    </ButtonGroupContext>
  )
}

import type { ComponentProps, ReactNode } from "react"

import type { ButtonColor, ButtonProps } from "@/components/ui/button/button.types"

/** `single` switches between options (one value, sliding indicator); `multiple` toggles filters. */
export type ButtonGroupSelection = "single" | "multiple"

export type ButtonGroupOrientation = "horizontal" | "vertical"

/** Scales the tray, its items (text, icons, padding) and the LEDs together. */
export type ButtonGroupSize = "xs" | "md" | "lg"

export type ButtonGroupBaseProps = Omit<
  ComponentProps<"div">,
  "children" | "className" | "defaultValue" | "onChange" | "dir" | "color"
> & {
  /** Names the group for screen readers and agents. */
  "aria-label": string
  className?: string
  children?: ReactNode
  /** Color of the lit items and the indicator. Defaults to `"primary"`. */
  color?: ButtonColor
  /** Size of the tray and every item. Defaults to `"md"`. */
  size?: ButtonGroupSize
  orientation?: ButtonGroupOrientation
  disabled?: boolean
}

export type ButtonGroupSingleProps = ButtonGroupBaseProps & {
  selection: "single"
  /** The chosen item's value. `null` means nothing chosen, which checks `ButtonGroupAll`. */
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (value: string | null) => void
  /** Submits the chosen value under this name. */
  name?: string
  required?: boolean
}

export type ButtonGroupMultipleProps = ButtonGroupBaseProps & {
  selection: "multiple"
  /** The pressed items' values. Empty means nothing pressed, which presses `ButtonGroupAll`. */
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
}

export type ButtonGroupProps = ButtonGroupSingleProps | ButtonGroupMultipleProps

export type ButtonGroupItemProps = Pick<
  ButtonProps,
  "icon" | "startIcon" | "endIcon" | "tooltip" | "disabled" | "aria-label" | "className" | "children"
> & {
  value: string
}

/** What ButtonGroup passes to its single-selection body. */
export type ButtonGroupSingleInternalProps = Omit<ButtonGroupSingleProps, "color" | "size"> & {
  hasAll: boolean
  /** The hover highlight, rendered first so it sits under the selection indicator. */
  highlight: ReactNode
}

/** What ButtonGroup passes to its multiple-selection body. */
export type ButtonGroupMultipleInternalProps = Omit<ButtonGroupMultipleProps, "color" | "size"> & {
  highlight: ReactNode
}

/** Where the hover highlight sits, in px from the group's padding box. */
export type ButtonGroupHighlightState = {
  left: number
  top: number
  width: number
  height: number
  /** A mouse is over an item of the group (touch has no hover). */
  visible: boolean
  /** Just appeared: placed without sliding from where it last was. */
  instant: boolean
}

export type ButtonGroupHighlightProps = {
  state: ButtonGroupHighlightState
}

export type ButtonGroupAllProps = Omit<ButtonGroupItemProps, "value">

export type ButtonGroupLedProps = {
  on: boolean
  size: ButtonGroupSize
}

export type ButtonGroupContextValue = {
  selection: ButtonGroupSelection
  color: ButtonColor
  size: ButtonGroupSize
  /** Called by ButtonGroupAll on mount; returns its unregister. */
  registerAll: () => () => void
}

export type UseControllableValueOptions<T> = {
  value: T | undefined
  defaultValue: T
  onValueChange: ((value: T) => void) | undefined
}

import type { ButtonColor, ButtonPadding } from "@/components/ui/button/button.types"

import type { ButtonGroupOrientation, ButtonGroupSelection, ButtonGroupSize } from "./button-group.types"

// Primary-colored brackets on two opposite corners, like the crop marks on a technical drawing.
// Duplicated from floating-toolbar on purpose: each registry component installs on its own.
const cornerMarkClasses = [
  "before:pointer-events-none before:absolute before:-top-px before:-left-px before:size-2 before:rounded-tl-sm before:border-t before:border-l before:border-primary",
  "after:pointer-events-none after:absolute after:-right-px after:-bottom-px after:size-2 after:rounded-br-sm after:border-r after:border-b after:border-primary",
].join(" ")

export const buttonGroupClasses = [
  "relative isolate inline-flex max-w-full flex-wrap items-center rounded-sm border border-border bg-card",
  cornerMarkClasses,
].join(" ")

// The tray's inset and the gap between items grow with the items.
export const buttonGroupSizeClasses = {
  xs: "gap-0.5 p-0.5",
  md: "gap-1 p-1",
  lg: "gap-1.5 p-1.5",
} satisfies Record<ButtonGroupSize, string>

// Each size is a step of the Button's padding scale, which also sets its text size; icon-only
// items get the matching square padding from the Button.
export const buttonGroupItemPadding = {
  xs: "xs",
  md: "sm",
  lg: "md",
} satisfies Record<ButtonGroupSize, ButtonPadding>

export const buttonGroupOrientationClasses = {
  horizontal: "flex-row",
  vertical: "flex-col items-stretch",
} satisfies Record<ButtonGroupOrientation, string>

// The indicator sits on the group, outside any Button, so the group sets the same --btn-* variables
// the Button's color does. Values duplicated from button.variants.ts.
export const buttonGroupColorClasses = {
  primary: "[--btn-color:var(--primary)] [--btn-accent:var(--primary)]",
  secondary: "[--btn-color:var(--secondary)] [--btn-accent:var(--secondary-foreground)]",
  muted: "[--btn-color:var(--muted)] [--btn-accent:var(--muted-foreground)]",
  info: "[--btn-color:var(--info)] [--btn-accent:var(--info)]",
  warning: "[--btn-color:var(--warning)] [--btn-accent:var(--warning)]",
  success: "[--btn-color:var(--success)] [--btn-accent:var(--success)]",
  error: "[--btn-color:var(--error)] [--btn-accent:var(--error)]",
} satisfies Record<ButtonColor, string>

// Slides to the chosen item with ui-sdk's measurements; marked like an open menu trigger on the
// toolbar and frame. Nothing chosen: ui-sdk gives it no box.
export const buttonGroupIndicatorClasses = [
  "absolute -z-10 top-(--segmented-control-indicator-top) left-(--segmented-control-indicator-left)",
  "w-(--segmented-control-indicator-width) h-(--segmented-control-indicator-height)",
  "bg-(--btn-accent)/15 inset-ring inset-ring-(--btn-accent)/50",
  "transition-[left,top,width,height] duration-200 ease-spring motion-reduce:transition-none",
].join(" ")

// The tray clips an outer ring, so the focus ring goes inside. A word wider than the tray (a narrow
// phone) breaks inside its item instead of pushing the tray past its container.
const itemBaseClasses =
  "group/item min-w-0 wrap-anywhere focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:inset-ring focus-visible:inset-ring-ring"

// In single, the checked item waits for the indicator to land, then its fill fades in over it.
// Only the fill and text wait: the focus ring, opacity and press keep their timing. The property
// list is restated here (same as the Button's) so the per-property delays line up with it.
const singleItemClasses = [
  "transition-[color,background-color,border-color,box-shadow,opacity,scale,translate]",
  "motion-safe:data-checked:[transition-delay:200ms,200ms,0s,0s,0s,0s,0s]",
].join(" ")

export const buttonGroupItemClasses = {
  single: `${itemBaseClasses} ${singleItemClasses}`,
  multiple: itemBaseClasses,
} satisfies Record<ButtonGroupSelection, string>

// A square LED before the label: dim when off, so items don't shift when they light up.
export const buttonGroupLedClasses =
  "shrink-0 bg-current opacity-25 transition-opacity duration-150 data-on:opacity-100 motion-reduce:transition-none"

export const buttonGroupLedSizeClasses = {
  xs: "size-1",
  md: "size-1.5",
  lg: "size-2",
} satisfies Record<ButtonGroupSize, string>

// Slides between items like the selection indicator, filled like an unlit item's hover. It fades in
// and out in place: only moves between items slide. Forced colors drop backgrounds, so it gets an
// outline there.
export const buttonGroupHighlightClasses = [
  "pointer-events-none absolute -z-10",
  "top-(--button-group-highlight-top) left-(--button-group-highlight-left)",
  "w-(--button-group-highlight-width) h-(--button-group-highlight-height)",
  "bg-muted-foreground/10 opacity-0 data-visible:opacity-100 forced-colors:outline forced-colors:outline-1",
  "transition-[left,top,width,height,opacity] duration-200 ease-spring data-instant:transition-opacity",
  "motion-reduce:transition-none",
].join(" ")

import { useCallback, useState } from "react"
import type { PointerEvent } from "react"

import type { ButtonGroupHighlightState } from "./button-group.types"

const HIDDEN: ButtonGroupHighlightState = { left: 0, top: 0, width: 0, height: 0, visible: false, instant: true }

/**
 * Tracks the item under a mouse or pen pointer, so one highlight can slide between items. Leaving an item
 * for the gap between items keeps it where it is; only leaving the group hides it.
 */
export function useButtonGroupHighlight() {
  const [state, setState] = useState(HIDDEN)

  const onPointerOver = useCallback((event: PointerEvent<HTMLElement>) => {
    // A tap fires pointerover too, but touch has no hover to show.
    if (event.pointerType === "touch") return
    if (!(event.target instanceof Element)) return
    const item = event.target.closest<HTMLElement>("[data-button-group-item]")
    if (item == null || !event.currentTarget.contains(item)) return
    if (item.matches("[data-disabled], [aria-disabled='true']")) return
    const { offsetLeft: left, offsetTop: top, offsetWidth: width, offsetHeight: height } = item
    setState((previous) => ({ left, top, width, height, visible: true, instant: !previous.visible }))
  }, [])

  const onPointerLeave = useCallback(() => {
    setState((previous) => (previous.visible ? { ...previous, visible: false } : previous))
  }, [])

  return { state, onPointerOver, onPointerLeave }
}

import { useCallback, useState } from "react"

import { BUTTON_GROUP_ALL } from "./button-group.constants"
import type { UseControllableValueOptions } from "./button-group.types"

// The consumer's value never holds the "All" item. ui-sdk's does: while nothing is chosen, All is
// the pressed (or checked) item, so it lights up and the arrow keys reach it like any other.

export function toSdkMultiple(value: string[]): string[] {
  return value.length === 0 ? [BUTTON_GROUP_ALL] : value
}

/** The consumer's next value for a ui-sdk change, or `undefined` when nothing should change. */
export function fromSdkMultiple(next: string[], current: string[]): string[] | undefined {
  const pressedAll = next.includes(BUTTON_GROUP_ALL)
  if (pressedAll && current.length > 0) return []
  if (!pressedAll && current.length === 0 && next.length === 0) return undefined
  return next.filter((item) => item !== BUTTON_GROUP_ALL)
}

export function toSdkSingle(value: string | null): string {
  return value ?? BUTTON_GROUP_ALL
}

export function fromSdkSingle(next: string | null): string | null {
  return next === BUTTON_GROUP_ALL ? null : next
}

function isSameValue(a: unknown, b: unknown): boolean {
  if (Array.isArray(a) && Array.isArray(b)) return a.length === b.length && a.every((item, i) => item === b[i])
  return Object.is(a, b)
}

/** Controlled when `value` is defined, uncontrolled from `defaultValue` otherwise. */
export function useControllableValue<T>({
  value,
  defaultValue,
  onValueChange,
}: UseControllableValueOptions<T>): [T, (next: T) => void] {
  const [internal, setInternal] = useState(defaultValue)
  const controlled = value !== undefined
  // Track the controlled value, so a group that stops being controlled keeps its last value
  // instead of jumping back to defaultValue.
  if (controlled && !isSameValue(internal, value)) setInternal(value)
  const current = controlled ? value : internal

  const setValue = useCallback(
    (next: T) => {
      if (isSameValue(next, current)) return
      if (!controlled) setInternal(next)
      onValueChange?.(next)
    },
    [controlled, current, onValueChange]
  )
  return [current, setValue]
}
